@Entity
public class Order {                 // aggregate root
    @Id Long id;
    @Version int version;            // one token for the cluster
    @OneToMany(mappedBy = "order", cascade = ALL)
    List<OrderLine> lines;
}

Order root = em.find(Order.class, id);
em.lock(root, LockModeType.OPTIMISTIC_FORCE_INCREMENT); // bump on commit
root.getLines().get(0).setQty(2);   // no per-line version column

Map<String, Object> scope = Map.of(
    "jakarta.persistence.lock.scope", PessimisticLockScope.EXTENDED);
Order root = em.find(Order.class, id,
    LockModeType.PESSIMISTIC_WRITE, scope);
for (OrderLine line : root.getLines()) {
    line.apply(delta);               // covered by the root lock
}
// release happens at transaction commit

